package alphametics

import "testing"

func TestEdgeCases(t *testing.T) {
	// Valid: single letter both sides with distinct letters is impossible; 0 == 0 trivial
	if _, err := Solve("A + A == B"); err != nil {
		t.Fatalf("A + A == B should solve: %v", err)
	}
	// Leading zero forbidden on result
	if _, err := Solve("A + B == C"); err != nil {
		// C is single digit so leading zero allowed; sum could be e.g. 1+2=3
		t.Logf("note: %v", err)
	}
	// trivial: 0 result
	if m, err := Solve("A + A == AA"); err != nil || m["A"] != 0 {
		t.Fatalf("A + A == AA expected error? got %v %v", m, err)
	}
}
